using System;
using System.IO;
using System.Reflection;
using CastleStorySteam;
static class DesktopUpdateSelfTest {
 internal static void Run(){string path=Assembly.GetExecutingAssembly().Location;byte[] app=File.ReadAllBytes(path),sig=File.ReadAllBytes(path+".sig");if(!DesktopRelease.Verify(BridgeVersion.Text,app,sig))throw new Exception("Desktop signature failed");if(DesktopRelease.Verify("9.9.9",app,sig))throw new Exception("Desktop version relabel accepted");byte[] bad=(byte[])app.Clone();bad[bad.Length/2]^=1;if(DesktopRelease.Verify(BridgeVersion.Text,bad,sig))throw new Exception("Desktop tampering accepted");if(UpdateVerifier.Verify(BridgeVersion.Text,app,sig))throw new Exception("Desktop signature accepted as a game DLL");byte[] blob=DesktopRelease.Build(BridgeVersion.Text,app,sig);string version;byte[] readApp,readSig;DesktopRelease.Parse(blob,out version,out readApp,out readSig);if(version!=BridgeVersion.Text||readApp.Length!=app.Length)throw new Exception("Desktop bundle round trip failed");foreach(byte[] corrupt in new byte[][]{new byte[0],new byte[DesktopRelease.MaxBytes+1],new byte[100],new byte[blob.Length-1]}){bool rejected=false;try{DesktopRelease.Parse(corrupt,out version,out readApp,out readSig);}catch{rejected=true;}if(!rejected)throw new Exception("Malformed desktop bundle accepted");}string root=Path.Combine(Path.GetTempPath(),"SteamBridgeDesktopTest_"+Guid.NewGuid().ToString("N"));string stored=DesktopRelease.Store(root,BridgeVersion.Text,app,sig);if(!DesktopRelease.Valid(stored,BridgeVersion.Text)||DesktopRelease.Store(root,BridgeVersion.Text,app,sig)!=stored)throw new Exception("Desktop cache failed");if(DesktopRelease.Latest(root,"0.0.0")!=stored)throw new Exception("Desktop forwarding failed");File.WriteAllBytes(stored,bad);if(DesktopRelease.Valid(stored,BridgeVersion.Text)||DesktopRelease.Latest(root,"0.0.0")!=null)throw new Exception("Tampered cached app selected");}
}
